import{_ as e,o as r,c as s,ah as o}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Transcripts and certificates","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/secretariat/releves-attestations.md","filePath":"src/en/guide/secretariat/releves-attestations.md"}'),a={name:"en/guide/secretariat/releves-attestations.md"};function i(n,t,c,d,h,p){return r(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="transcripts-and-certificates" tabindex="-1">Transcripts and certificates <a class="header-anchor" href="#transcripts-and-certificates" aria-label="Permalink to &quot;Transcripts and certificates&quot;">​</a></h1><p>In a higher education institution, the secretariat prints the documents juries have published: <strong>transcripts</strong>, session by session, and <strong>certificates of completion</strong>. Open <strong>Higher education → Transcripts and certificates</strong>. The administrator can use it too.</p><p>Only published results appear here: a deliberation in progress, or reopened, prints nothing until the jury closes it.</p><h2 id="for-one-student-at-the-desk" tabindex="-1">For one student, at the desk <a class="header-anchor" href="#for-one-student-at-the-desk" aria-label="Permalink to &quot;For one student, at the desk&quot;">​</a></h2><p>Type their <strong>name</strong>, or their <strong>registration number</strong> if the school uses them, then <strong>Search</strong>. For each student found, the page lists:</p><ul><li>their certificate of completion, if they completed their programme;</li><li>their transcripts, latest first: promotion, year and session (first session or retake).</li></ul><p><strong>Transcript</strong> or <strong>Certificate</strong> downloads the document as a PDF.</p><h2 id="for-a-whole-promotion" tabindex="-1">For a whole promotion <a class="header-anchor" href="#for-a-whole-promotion" aria-label="Permalink to &quot;For a whole promotion&quot;">​</a></h2><p>Under <strong>By promotion</strong>, choose the <strong>year</strong>. Each promotion with a published session offers:</p><ul><li><strong>Transcripts — First session</strong> and <strong>Transcripts — Retake</strong>: every student&#39;s transcript, a page each;</li><li><strong>Certificates</strong>: the certificates already issued to its graduates.</li></ul><p>The secretariat prints certificates but does not issue them: the administrator or the programme&#39;s head does, from the promotion&#39;s <strong>Graduates</strong> page.</p>',11)])])}const g=e(a,[["render",i]]);export{u as __pageData,g as default};
